Based on my understanding of the B+ tree structure from the header file:

1. Node has:
   - `isLeaf` - boolean to check if it's a leaf node
   - `keys` - vector of integers
   - `ptr2TreeOrData` - union that holds either:
     - `ptr2Tree` - vector of Node* for internal nodes
     - `dataPtr` - vector of FILE* for leaf nodes

2. For search:
   - Start at root
   - Use binary search to find the appropriate child/position
   - If leaf node, search for the key in the keys vector
   - If internal node, navigate to the appropriate child

Let me implement the search_key function:

```cpp
bool search_key(Node* root, int key) {
    if (root == nullptr) {
        return false;
    }

    Node* cursor = root;

    // Navigate from root to leaf
    while (!cursor->isLeaf) {
        // Binary search to find the appropriate child
        auto& keys = cursor->keys;
        int i = 0;
        for (i = 0; i < static_cast<int>(keys.size()); i++) {
            if (key < keys[i]) {
                break;
            }
        }
        cursor = cursor->ptr2TreeOrData.ptr2Tree[i];
    }

    // Now at leaf node, search for the key
    auto& leafKeys = cursor->keys;
    for (int i = 0; i < static_cast<int>(leafKeys.size()); i++) {
        if (leafKeys[i] == key) {
            return true;
        }
    }

    return false;
}
```

